package dns

import (
	"context"
	"os"
	"testing"
	"time"

	"mongo-journald/internal/model"
)

// monitor.jsonl is synthetic (edge cases: CNAME chains, JSON-only RRs,
// NXDOMAIN, timeout, junk lines): it follows the message layout resolved builds
// in manager_monitor_send (state/rcode/question/collectedQuestions/answer
// with rr + raw), with wire-format raw RRs generated by dnsmessage.
func readFixture(t *testing.T, ignore []string) []model.Doc {
	t.Helper()
	return readFile(t, "testdata/monitor.jsonl", ignore)
}

func readFile(t *testing.T, path string, ignore []string) []model.Doc {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	out := make(chan model.Record, 100)
	r := NewStream(Options{Hostname: "h1", Retention: 72 * time.Hour, Ignore: ignore}, f)
	if err := r.Run(context.Background(), out); err != nil {
		t.Fatal(err)
	}
	close(out)
	var docs []model.Doc
	for rec := range out {
		docs = append(docs, rec.Doc)
	}
	return docs
}

func TestFixture(t *testing.T) {
	docs := readFixture(t, nil)
	if len(docs) != 6 {
		t.Fatalf("got %d docs, want 6 (ready line and bad json skipped)", len(docs))
	}

	d := docs[0]
	if d["qname"] != "www.github.com" || d["qtype"] != "A" || d["rcode"] != "NOERROR" || d["server"] != "h1" {
		t.Fatalf("doc0 = %v", d)
	}
	if d["cname"] != "github.com" {
		t.Errorf("cname = %v", d["cname"])
	}
	ans := d["answers"].([]model.Doc)
	if len(ans) != 2 || ans[1]["data"] != "140.82.112.3" || ans[1]["ttl"] != int64(60) || ans[0]["type"] != "CNAME" {
		t.Errorf("answers = %v", ans)
	}
	at := d["at"].(time.Time)
	if !d["expireAt"].(time.Time).Equal(at.Add(72 * time.Hour)) {
		t.Errorf("expireAt = %v", d["expireAt"])
	}

	if d := docs[1]; d["qname"] != "example.com" || d["qtype"] != "AAAA" ||
		d["answers"].([]model.Doc)[0]["data"] != "2606:2800:21f:cb07::6820" {
		t.Errorf("doc1 = %v", d)
	}
	// JSON-only fallback (no raw)
	if a := docs[2]["answers"].([]model.Doc)[0]; a["data"] != "5 gmail-smtp-in.l.google.com" || a["type"] != "MX" {
		t.Errorf("mx = %v", a)
	}
	if d := docs[3]; d["rcode"] != "NXDOMAIN" || d["state"] != "rcode-failure" || d["answers"] != nil {
		t.Errorf("nxdomain = %v", d)
	}
	if d := docs[4]; d["rcode"] != nil || d["state"] != "timeout" {
		t.Errorf("timeout = %v", d)
	}
	if a := docs[5]["answers"].([]model.Doc)[0]; a["data"] != "100.64.0.7" {
		t.Errorf("json A = %v", a)
	}
}

func TestIgnore(t *testing.T) {
	docs := readFixture(t, []string{"ts.net", "invalid."})
	if len(docs) != 4 {
		t.Fatalf("got %d docs, want 4", len(docs))
	}
	if Ignored("notts.net", []string{"ts.net"}) {
		t.Error("suffix match must respect label boundaries")
	}
}

func TestRollupKey(t *testing.T) {
	docs := readFixture(t, nil)
	k, inc := RollupKey(docs[3])
	if k[0] != "nonexistent-zz9.invalid" || k[1] != "A" || k[2] != "NXDOMAIN" || inc["n"] != 1 {
		t.Errorf("key=%v inc=%v", k, inc)
	}
	if k, _ := RollupKey(docs[4]); k[2] != "timeout" {
		t.Errorf("timeout key = %v", k)
	}
}

func TestNames(t *testing.T) {
	if typeName(65) != "TYPE65" && typeName(65) != "HTTPS" {
		t.Errorf("type 65 = %q", typeName(65))
	}
	if RCodeName(2) != "SERVFAIL" || RCodeName(99) != "RCODE99" {
		t.Error("rcode names")
	}
	if NormName(".") != "." || NormName("A.B.") != "a.b" {
		t.Error("NormName")
	}
}

// dev-real.jsonl is a real `resolvectl monitor --json=short` capture from dev.
func TestRealCapture(t *testing.T) {
	docs := readFile(t, "testdata/dev-real.jsonl", nil)
	if len(docs) != 3 {
		t.Fatalf("got %d docs, want 3", len(docs))
	}
	if d := docs[0]; d["qname"] != "slashdot.org" || d["qtype"] != "A" || d["rcode"] != "NOERROR" || d["nodata"] != nil {
		t.Errorf("A = %v", d)
	} else if a := d["answers"].([]model.Doc); len(a) != 2 || a[0]["data"] != "104.18.4.215" || a[1]["data"] != "104.18.5.215" || a[0]["ttl"] != int64(300) {
		t.Errorf("A answers = %v", a)
	}
	// AAAA with no AAAA records: resolved returns the SOA only
	d := docs[1]
	if d["qtype"] != "AAAA" || d["rcode"] != "NOERROR" || d["nodata"] != true {
		t.Errorf("NODATA = %v", d)
	}
	if a := d["answers"].([]model.Doc)[0]; a["type"] != "SOA" || a["data"] != "ns11.constellix.com dns.constellix.com" || a["ttl"] != int64(180) {
		t.Errorf("SOA = %v", a)
	}
	d = docs[2]
	if d["qname"] != "215.4.18.104.in-addr.arpa" || d["qtype"] != "PTR" || d["state"] != "errno" ||
		d["errno"] != 113 || d["error"] != "no route to host" || d["rcode"] != nil || d["nodata"] != nil {
		t.Errorf("errno = %v", d)
	}
	if k, _ := RollupKey(d); k[2] != "errno" {
		t.Errorf("errno rollup key = %v", k)
	}
}
